#!ibl edition=2
# 41회차 v2 (수정 2·3: changelog 제목 null 보간 → ?: 안 도구 호출 → 함수, null 가능 숫자 보간 → 함수가 Text row 생성) ← v1 (수정 1: changelog 보간 안 이스케이프 따옴표 SYNTAX → 값을 먼저 꺼냄) ← 최초 초안 — 사용자 실험 연구 보고서. inputs: src(자료 폴더), out(출력 폴더), prev(이전 out 폴더 또는 null)

# ---- 순수 계산 ----
[def:평균]($xs) { return sum($xs) / len($xs) }
[def:표준편차]($xs) {
  $m = [fn:평균]{xs:$xs}
  return (sum(map($xs,($x)=>($x - $m) * ($x - $m))) / (len($xs) - 1)) ** 0.5
}
[def:수인가]($v) {
  [try] { $x = number($v); return true } [catch] { return false }
}
[def:임계]($tc,$df,$col) {
  $row = get($tc,text(min($df,120)))
  return $col == "p05" ? $row.p05 : $row.p0125
}
[def:조건통계]($g,$t,$xs,$tc) {
  $n = len($xs)
  [if:$n < 2] { return {group:$g,task:$t,n:$n,mean:$n == 1 ? $xs[0] : null,sd:null,ci_low:null,ci_high:null,half:null,row:f"| ${g} | ${t} | ${n} | — | — | — |"} }
  $m = [fn:평균]{xs:$xs}
  $s = [fn:표준편차]{xs:$xs}
  $half = [fn:임계]{tc:$tc,df:$n - 1,col:"p05"} * $s / ($n ** 0.5)
  $mean_r = round($m,3)
  $sd_r = round($s,3)
  $lo = round($m - $half,3)
  $hi = round($m + $half,3)
  return {group:$g,task:$t,n:$n,mean:$mean_r,sd:$sd_r,ci_low:$lo,ci_high:$hi,half:round($half,3),row:f"| ${g} | ${t} | ${n} | ${mean_r} | ${sd_r} | ${lo} ~ ${hi} |"}
}
[def:웰치]($xa,$xb,$tc) {
  $na = len($xa)
  $nb = len($xb)
  [if:$na < 8 or $nb < 8] { return {testable:false,n_a:$na,n_b:$nb,row:f"${na}/${nb} | — | — | — | — | —"} }
  $ma = [fn:평균]{xs:$xa}
  $mb = [fn:평균]{xs:$xb}
  $sa = [fn:표준편차]{xs:$xa}
  $sb = [fn:표준편차]{xs:$xb}
  $va = $sa * $sa / $na
  $vb = $sb * $sb / $nb
  $t = ($mb - $ma) / (($va + $vb) ** 0.5)
  $df = round((($va + $vb) * ($va + $vb)) // ($va * $va / ($na - 1) + $vb * $vb / ($nb - 1)))
  $pooled = ((($na - 1) * $sa * $sa + ($nb - 1) * $sb * $sb) / ($na + $nb - 2)) ** 0.5
  $crit = [fn:임계]{tc:$tc,df:$df,col:"p0125"}
  $ma_r = round($ma,3)
  $mb_r = round($mb,3)
  $t_r = round($t,4)
  $d_r = round(($mb - $ma) / $pooled,4)
  return {testable:true,n_a:$na,n_b:$nb,mean_a:$ma_r,mean_b:$mb_r,t:$t_r,df:$df,t_crit_0125:$crit,significant:abs($t) > $crit,cohen_d:$d_r,row:f"${na}/${nb} | ${ma_r} / ${mb_r} | ${t_r} | ${df} | ${crit} | ${d_r}"}
}
[def:판정]($h,$w) {
  [if:not $w.testable] { return "검정 불가" }
  $dir = $w.mean_b < $w.mean_a ? "B<A" : "B>A"
  [if:$w.significant] { return $dir == $h.direction ? "지지" : "불지지(반대 방향 유의)" }
  return "불지지(비유의 — 차이 없음 입증 아님)"
}
